234		createSessionViaHTTP(t, h, "dev", "sess")
235	
236		// Never-created session -> 404 JSON with no results.
237		w, body := postSessionChanges(t, h, "ghost", "doc1", `{"changes":[{"id":"a","payload":1}]}`)
238		if w.Code != http.StatusNotFound || body["error"] == nil {
239			t.Fatalf("unknown session = %d %v", w.Code, body)
240		}
241		if body["results"] != nil {
242			t.Fatalf("404 leaked results: %s", w.Body.String())
243		}
244	
245		// Request shape precedes the session lookup: a malformed batch against an
246		// unknown session is still a 400.
247		w, _ = postSessionChanges(t, h, "ghost", "doc1", `{"changes":[{"id":"a","payload":1}]}trailing`)
248		if w.Code != http.StatusBadRequest {
249			t.Fatalf("bad shape + missing session = %d, want 400", w.Code)
250		}
251	
252		// Delete the session -> commits through it now 404.
253		w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/sess")
254		if w.Code != http.StatusOK {
255			t.Fatal(w.Body.String())
256		}
257		w, body = postSessionChanges(t, h, "sess", "doc1", `{"changes":[{"id":"a","payload":1}]}`)
258		if w.Code != http.StatusNotFound || body["error"] == nil {
259			t.Fatalf("deleted session = %d %v", w.Code, body)
260		}
261	
262		// Zero writes: nothing reached the change log.
263		rows, next, _ := s.ListChanges("doc1", 0, 100)
264		if len(rows) != 0 || next != 0 {
265			t.Fatalf("zero-write violated: rows = %v next = %d", rows, next)
266		}
