270		h, s := newTestHandler(t)
271		createSessionViaHTTP(t, h, "dev", "sess")
272	
273		w, _ := postJSON(t, h, "/v1/documents/doc1/permissions", map[string]any{"deviceId": "dev", "action": "revoke"})
274		if w.Code != http.StatusOK {
275			t.Fatal(w.Body.String())
276		}
277	
278		// Revoked: 403 JSON with no results and zero writes.
279		w, body := postSessionChanges(t, h, "sess", "doc1", `{"changes":[{"id":"a","payload":1}]}`)
280		if w.Code != http.StatusForbidden || body["error"] == nil {
281			t.Fatalf("revoked = %d %v", w.Code, body)
282		}
283		if body["results"] != nil {
284			t.Fatalf("403 leaked results: %s", w.Body.String())
285		}
286	
287		// Session existence precedes the permission check: an unknown session
288		// against a revoked document is a 404, not a 403.
289		w, _ = postSessionChanges(t, h, "ghost", "doc1", `{"changes":[{"id":"a","payload":1}]}`)
290		if w.Code != http.StatusNotFound {
291			t.Fatalf("missing session + revoked doc = %d, want 404", w.Code)
292		}
293	
294		rows, next, _ := s.ListChanges("doc1", 0, 100)
295		if len(rows) != 0 || next != 0 {
296			t.Fatalf("zero-write violated: rows = %v next = %d", rows, next)
297		}
298	
299		// Re-grant restores the commit path.
300		w, _ = postJSON(t, h, "/v1/documents/doc1/permissions", map[string]any{"deviceId": "dev", "action": "grant"})
301		if w.Code != http.StatusOK {
302			t.Fatal(w.Body.String())
303		}
304		w, body = postSessionChanges(t, h, "sess", "doc1", `{"changes":[{"id":"a","payload":1}]}`)
305		if w.Code != http.StatusOK {
306			t.Fatalf("re-granted commit = %d %s", w.Code, w.Body.String())
307		}
308		r := body["results"].([]any)[0].(map[string]any)
309		if r["created"] != true || r["cursor"].(float64) != 1 {
310			t.Fatalf("re-granted result = %v", r)
311		}
312	}
