319		for _, method := range []string{http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodOptions} {
320			w, _ := doRequest(t, h, method, sessionChangesPath("sess", "doc1"))
321			if w.Code != http.StatusBadRequest {
