419	func TestSessionPostChangesHTTPConcurrent(t *testing.T) {
420		h, _ := newTestHandler(t)
421		createSessionViaHTTP(t, h, "dev", "sess")
422	
423		const n = 40
424		var wg sync.WaitGroup
425		errs := make(chan error, n)
426		for i := 0; i < n; i++ {
427			wg.Add(1)
428			go func(i int) {
429				defer wg.Done()
430				w, _ := postSessionChanges(t, h, "sess", "doc", map[string]any{
431					"changes": []any{map[string]any{"id": fmt.Sprintf("id-%02d", i), "payload": map[string]any{"i": i}}},
432				})
433				if w.Code != http.StatusOK {
434					errs <- fmt.Errorf("post %d status %d: %s", i, w.Code, w.Body.String())
435				}
436			}(i)
437		}
438		wg.Wait()
439		close(errs)
440		for err := range errs {
441			t.Error(err)
442		}
443	
444		// No cursor is allocated twice and no record is lost.
445		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
446		if w.Code != http.StatusOK {
447			t.Fatal(w.Body.String())
448		}
449		rows := body["changes"].([]any)
450		if len(rows) != n || body["nextCursor"].(float64) != n {
451			t.Fatalf("stored %d changes, nextCursor = %v, want %d", len(rows), body["nextCursor"], n)
452		}
453		seen := make(map[float64]bool, n)
454		for _, row := range rows {
455			cursor := row.(map[string]any)["cursor"].(float64)
456			if seen[cursor] {
457				t.Fatalf("cursor %v allocated twice", cursor)
458			}
459			seen[cursor] = true
