463	func TestSessionPostChangesHTTPPersistenceAcrossRestart(t *testing.T) {
464		path := filepath.Join(t.TempDir(), "session-post-changes.db")
465	
466		s, err := app.Open(path)
467		if err != nil {
468			t.Fatal(err)
469		}
470		h := NewHandler(s)
471		createSessionViaHTTP(t, h, "dev", "sess")
472		w, _ := postSessionChanges(t, h, "sess", "doc1", `{"changes":[
473			{"id":"c1","payload":{"a":1}},
474			{"id":"c2","payload":[1,true,null]}
475		]}`)
476		if w.Code != http.StatusOK {
477			t.Fatal(w.Body.String())
478		}
479		if err := s.Close(); err != nil {
480			t.Fatal(err)
481		}
482	
483		s2, err := app.Open(path)
484		if err != nil {
485			t.Fatal(err)
486		}
487		t.Cleanup(func() { _ = s2.Close() })
488		h2 := NewHandler(s2)
489	
490		// Idempotency survives the restart: same session device and decoded
491		// payload -> created=false with the first cursor.
492		w, body := postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c1","payload":{"a":1}}]}`)
493		if w.Code != http.StatusOK {
494			t.Fatal(w.Body.String())
495		}
