497		if r["created"] != false || r["cursor"].(float64) != 1 {
498			t.Fatalf("idempotent after restart = %v", r)
499		}
500	
501		// So does the conflict decision.
502		w, body = postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c1","payload":{"a":2}}]}`)
503		if w.Code != http.StatusConflict || body["conflictId"] != "c1" {
504			t.Fatalf("conflict after restart = %d %s", w.Code, w.Body.String())
505		}
506	
507		// Raw payloads read back verbatim and the cursor space continues.
508		w, body = doRequest(t, h2, http.MethodGet, "/v1/documents/doc1/changes")
509		if w.Code != http.StatusOK {
510			t.Fatal(w.Body.String())
511		}
512		rows := body["changes"].([]any)
513		if len(rows) != 2 || body["nextCursor"].(float64) != 2 {
514			t.Fatalf("list after restart = %v next=%v", rows, body["nextCursor"])
515		}
516		second := rows[1].(map[string]any)
517		if second["deviceId"] != "dev" {
518			t.Fatalf("device after restart = %v", second)
519		}
520		payload := second["payload"].([]any)
521		if len(payload) != 3 || payload[0].(float64) != 1 || payload[1] != true || payload[2] != nil {
522			t.Fatalf("payload after restart = %v", second["payload"])
523		}
524	
525		w, body = postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c3","payload":42}]}`)
526		if w.Code != http.StatusOK {
527			t.Fatal(w.Body.String())
528		}
529		r = body["results"].([]any)[0].(map[string]any)
530		if r["created"] != true || r["cursor"].(float64) != 3 {
531			t.Fatalf("post-restart cursor = %v", r)
532		}
