	h, _ := newTestHandler(t)
	seedDoc(t, h, "doc1", 2)

	w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":2,"state":{"text":"hello","n":1}}`)
	if w.Code != http.StatusOK {
		t.Fatalf("post status = %d body = %s", w.Code, w.Body.String())
