1	package server
2	
3	import (
4		"bufio"
5		"crypto/rand"
6		"crypto/sha1"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/json"
10		"fmt"
11		"io"
12		"net"
13		"net/http"
14		"net/http/httptest"
15		"net/url"
16		"path/filepath"
17		"strings"
18		"testing"
