21		"github.com/alicegogogogogo/local-first-sync-service/internal/app"
22		"github.com/alicegogogogogo/local-first-sync-service/internal/events"
23	)
24	
25	// wsClient is a minimal raw RFC 6455 client used to drive the subscription
26	// endpoint over a real TCP connection (HTTP hijacking does not work with
27	// httptest.ResponseRecorder).
28	type wsClient struct {
29		t    *testing.T
30		conn net.Conn
31		br   *bufio.Reader
32	}
33	
34	func newWSKey() string {
35		b := make([]byte, 16)
36		_, _ = rand.Read(b)
37		return base64.StdEncoding.EncodeToString(b)
38	}
39	
40	// dialWS performs the opening handshake against an httptest.Server URL. A
41	// non-101 response is returned as (nil, response) so tests can assert the
42	// 400/403/404 JSON failures.
43	func dialWS(t *testing.T, serverURL string) (*wsClient, *http.Response) {
44		t.Helper()
45		u, err := url.Parse(serverURL)
46		if err != nil {
47			t.Fatal(err)
48		}
49		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
50		if err != nil {
51			t.Fatalf("dial: %v", err)
52		}
53		key := newWSKey()
54		req := fmt.Sprintf(
55			"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"+
56				"Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n",
57			u.RequestURI(), u.Host, key)
58		if _, err := io.WriteString(conn, req); err != nil {
59			_ = conn.Close()
60			t.Fatalf("write handshake: %v", err)
61		}
62		br := bufio.NewReader(conn)
63		resp, err := http.ReadResponse(br, nil)
64		if err != nil {
65			_ = conn.Close()
66			t.Fatalf("read handshake: %v", err)
67		}
68		if resp.StatusCode != http.StatusSwitchingProtocols {
69			_ = conn.Close()
70			return nil, resp
71		}
72		sum := sha1.Sum([]byte(key + wsGUID))
73		if got := resp.Header.Get("Sec-WebSocket-Accept"); got != base64.StdEncoding.EncodeToString(sum[:]) {
74			_ = conn.Close()
75			t.Fatalf("accept = %q, want the RFC 6455 digest", got)
76		}
77		return &wsClient{t: t, conn: conn, br: br}, resp
78	}
79	
80	// dialWSRaw sends a caller-built handshake request, for negative tests that
81	// omit or corrupt a header.
82	func dialWSRaw(t *testing.T, serverURL, requestTarget string, headers ...string) (*http.Response, net.Conn) {
83		t.Helper()
84		u, err := url.Parse(serverURL)
85		if err != nil {
86			t.Fatal(err)
87		}
88		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
89		if err != nil {
90			t.Fatalf("dial: %v", err)
91		}
92		var b strings.Builder
93		b.WriteString("GET " + requestTarget + " HTTP/1.1\r\n")
94		b.WriteString("Host: " + u.Host + "\r\n")
95		for _, h := range headers {
96			b.WriteString(h + "\r\n")
97		}
98		b.WriteString("\r\n")
99		if _, err := io.WriteString(conn, b.String()); err != nil {
100			_ = conn.Close()
101			t.Fatalf("write handshake: %v", err)
102		}
103		br := bufio.NewReader(conn)
104		resp, err := http.ReadResponse(br, nil)
105		if err != nil {
106			_ = conn.Close()
107			t.Fatalf("read handshake: %v", err)
108		}
109		return resp, conn
110	}
111	
112	// readFrame reads one server (unmasked) frame.
113	func (c *wsClient) readFrame() (fin bool, opcode byte, payload []byte) {
114		c.t.Helper()
115		header := make([]byte, 2)
116		if _, err := io.ReadFull(c.br, header); err != nil {
117			c.t.Fatalf("read frame header: %v", err)
118		}
119		fin = header[0]&0x80 != 0
120		opcode = header[0] & 0x0F
121		length := int64(header[1] & 0x7F)
122		switch length {
123		case 126:
124			var ext [2]byte
125			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
126				c.t.Fatalf("read ext len: %v", err)
127			}
128			length = int64(binary.BigEndian.Uint16(ext[:]))
129		case 127:
130			var ext [8]byte
131			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
132				c.t.Fatalf("read ext len: %v", err)
133			}
134			length = int64(binary.BigEndian.Uint64(ext[:]))
135		}
136		payload = make([]byte, length)
137		if length > 0 {
138			if _, err := io.ReadFull(c.br, payload); err != nil {
139				c.t.Fatalf("read payload: %v", err)
140			}
141		}
142		return fin, opcode, payload
143	}
144	
145	func closeCode(payload []byte) int {
146		if len(payload) < 2 {
147			return -1
148		}
149		return int(binary.BigEndian.Uint16(payload[:2]))
150	}
151	
152	// readFrameMaybe is the non-fatal variant used by negative assertions: with a
153	// read deadline already set it reports ok=false on a timeout/EOF instead of
154	// failing the test.
155	func (c *wsClient) readFrameMaybe() (fin bool, opcode byte, payload []byte, ok bool) {
156		header := make([]byte, 2)
157		if _, err := io.ReadFull(c.br, header); err != nil {
158			return false, 0, nil, false
159		}
160		fin = header[0]&0x80 != 0
161		opcode = header[0] & 0x0F
162		length := int64(header[1] & 0x7F)
163		switch length {
164		case 126:
165			var ext [2]byte
166			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
167				return false, 0, nil, false
168			}
169			length = int64(binary.BigEndian.Uint16(ext[:]))
170		case 127:
171			var ext [8]byte
172			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
173				return false, 0, nil, false
174			}
175			length = int64(binary.BigEndian.Uint64(ext[:]))
176		}
177		payload = make([]byte, length)
178		if length > 0 {
179			if _, err := io.ReadFull(c.br, payload); err != nil {
180				return false, 0, nil, false
181			}
182		}
183		return fin, opcode, payload, true
184	}
185	
186	// readChange reads the next complete text message and decodes one change row.
187	// The server only ever sends whole (FIN) text frames; pongs are skipped.
188	func (c *wsClient) readChange() events.ListedChange {
189		c.t.Helper()
190		for {
191			fin, opcode, payload := c.readFrame()
192			switch opcode {
193			case wsOpcodeText:
194				if !fin {
195					c.t.Fatal("server sent a fragmented text frame")
196				}
197				var change events.ListedChange
198				if err := json.Unmarshal(payload, &change); err != nil {
199					c.t.Fatalf("text frame is not a change row: %s (%v)", payload, err)
200				}
201				return change
202			case wsOpcodePong:
203				continue
204			case wsOpcodeClose:
205				c.t.Fatalf("unexpected close frame while reading change: code=%d", closeCode(payload))
206			default:
207				c.t.Fatalf("unexpected opcode %d while reading change", opcode)
208			}
209		}
210	}
211	
212	// readCloseCode reads frames until the close frame and returns its code.
213	func (c *wsClient) readCloseCode() int {
214		c.t.Helper()
215		for {
216			_, opcode, payload := c.readFrame()
217			if opcode == wsOpcodeClose {
218				return closeCode(payload)
219			}
220		}
221	}
222	
223	// sendMasked writes one masked client frame.
224	func (c *wsClient) sendMasked(opcode byte, payload []byte) {
225		c.t.Helper()
226		mask := make([]byte, 4)
227		_, _ = rand.Read(mask)
228		masked := append([]byte(nil), payload...)
229		for i := range masked {
230			masked[i] ^= mask[i%4]
231		}
232		var header []byte
233		b0 := byte(0x80) | opcode
234		switch {
235		case len(payload) <= 125:
236			header = append(header, b0, 0x80|byte(len(payload)))
237		case len(payload) <= 65535:
238			header = append(header, b0, 0x80|126)
239			ext := make([]byte, 2)
240			binary.BigEndian.PutUint16(ext, uint16(len(payload)))
241			header = append(header, ext...)
242		default:
243			header = append(header, b0, 0x80|127)
244			ext := make([]byte, 8)
245			binary.BigEndian.PutUint64(ext, uint64(len(payload)))
246			header = append(header, ext...)
247		}
248		header = append(header, mask...)
249		if _, err := c.conn.Write(header); err != nil {
250			c.t.Fatalf("write frame header: %v", err)
251		}
252		if len(masked) > 0 {
253			if _, err := c.conn.Write(masked); err != nil {
254				c.t.Fatalf("write frame payload: %v", err)
255			}
256		}
257	}
258	
259	func (c *wsClient) sendText(payload string) { c.sendMasked(wsOpcodeText, []byte(payload)) }
260	func (c *wsClient) sendPing()               { c.sendMasked(wsOpcodePing, nil) }
261	
262	func (c *wsClient) setReadDeadline(d time.Duration) {
263		_ = c.conn.SetReadDeadline(time.Now().Add(d))
264	}
265	func (c *wsClient) clearReadDeadline() { _ = c.conn.SetReadDeadline(time.Time{}) }
266	
267	func (c *wsClient) sendClose(code int) {
268		payload := make([]byte, 2)
269		binary.BigEndian.PutUint16(payload, uint16(code))
270		c.sendMasked(wsOpcodeClose, payload)
271	}
272	
273	func (c *wsClient) close() { _ = c.conn.Close() }
274	
275	// --- fixtures ---------------------------------------------------------------
276	
277	func newWSTestServer(t *testing.T) (*httptest.Server, *app.App) {
278		t.Helper()
279		st, err := app.Open(filepath.Join(t.TempDir(), "ws.db"))
280		if err != nil {
281			t.Fatal(err)
282		}
283		srv := httptest.NewServer(NewHandler(st))
284		t.Cleanup(srv.Close)
285		t.Cleanup(func() { _ = st.Close() })
286		return srv, st
287	}
288	
289	// setupSession registers a device owning a session and seeds the document with
290	// changes seed-1..seed-N, each carrying {"n":i}, via the public HTTP surface.
291	func setupSession(t *testing.T, srv *httptest.Server, device, session, doc string, seed int) {
292		t.Helper()
293		httpPost := func(path string, body any) {
294			raw, _ := json.Marshal(body)
295			resp, err := srv.Client().Post(srv.URL+path, "application/json", strings.NewReader(string(raw)))
296			if err != nil {
297				t.Fatalf("POST %s: %v", path, err)
298			}
299			defer resp.Body.Close()
300			if resp.StatusCode != http.StatusOK {
301				data, _ := io.ReadAll(resp.Body)
302				t.Fatalf("POST %s = %d %s", path, resp.StatusCode, data)
303			}
304		}
305		httpPost("/v1/devices", map[string]any{"deviceId": device})
306		httpPost("/v1/devices/"+device+"/sessions", map[string]any{"sessionId": session})
307		for i := 0; i < seed; i++ {
308			httpPost("/v1/documents/"+doc+"/changes", map[string]any{
309				"deviceId": device,
310				"changes": []any{
311					map[string]any{"id": fmt.Sprintf("seed-%d", i+1), "payload": map[string]any{"n": i + 1}},
312				},
313			})
314		}
315	}
316	
317	func subscribeURL(srv *httptest.Server, session, doc, cursor string) string {
318		return srv.URL + "/v1/sessions/" + session + "/documents/" + doc + "/changes/subscribe?cursor=" + cursor
319	}
