// MergeChangeAuthorized validates and appends one change against a
// caller-observed base cursor with exactly the merge semantics of
// MergeChange, but enforces the gate (registration then permission) first in
// the same serialized transaction: an unregistered device yields
// store.ErrDeviceNotFound and a revoked device yields ErrPermissionDenied.
// None of those outcomes writes anything or exposes change content. It is the
// session-scoped merge entry: the device identity is resolved from the session
// by the HTTP layer before the call.
func (s *Service) MergeChangeAuthorized(documentID string, baseCursor int64, c Change) (MergeResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return MergeResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before any
	// change content is observed, so a rejected merge cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, c.DeviceID); err != nil {
			return MergeResult{}, err
		}
	}

	result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
	if err != nil {
		return MergeResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return MergeResult{}, err
	}
	if appended {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

