216	// MergeChange validates and appends one change against a caller-observed base
217	// cursor, all within a single serialized transaction.
218	//
219	//   - An existing id is idempotent only when deviceId and the decoded payload
220	//     match (Outcome "idempotent", with the original Result); a mismatch is an
221	//     *ErrConflict and nothing is written.
222	//   - A new id with baseCursor equal to the current cursor is appended as
223	//     "applied".
224	//   - A new id with a base cursor behind the current one is appended as
225	//     "merged" only when every change after baseCursor carries a JSON object
226	//     payload whose top-level keys are disjoint from the new payload's; any
227	//     non-object later payload or shared key is an *ErrConflict.
228	//
229	// A non-zero baseCursor for an unknown document, or a baseCursor greater than
230	// the current cursor, returns ErrStaleCursor. A baseCursor below the
231	// compaction boundary returns ErrCompactedBase: the changes the merge would be
232	// checked against have left the online log, so the conflict check cannot be
233	// completed. An unknown document with baseCursor 0 accepts the first change as
234	// "applied".
235	// MergeChangeAuthorized validates and appends one change against a
236	// caller-observed base cursor with exactly the merge semantics of
237	// MergeChange, but enforces the gate (registration then permission) first in
238	// the same serialized transaction: an unregistered device yields
239	// store.ErrDeviceNotFound and a revoked device yields ErrPermissionDenied.
240	// None of those outcomes writes anything or exposes change content. It is the
241	// session-scoped merge entry: the device identity is resolved from the session
242	// by the HTTP layer before the call.
243	func (s *Service) MergeChangeAuthorized(documentID string, baseCursor int64, c Change) (MergeResult, error) {
244		tx, err := s.db.Begin()
245		if err != nil {
246			return MergeResult{}, err
247		}
248		defer func() { _ = tx.Rollback() }()
249	
250		// Gate first: the device row and the permission row are read before any
251		// change content is observed, so a rejected merge cannot reveal anything.
252		if s.gate != nil {
253			if err := s.gate.DeviceAuthorizedTx(tx, documentID, c.DeviceID); err != nil {
254				return MergeResult{}, err
255			}
256		}
257	
258		result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
259		if err != nil {
260			return MergeResult{}, err
261		}
262		if err := tx.Commit(); err != nil {
263			return MergeResult{}, err
